from math import isfinite

def validate_reset_token(submitted_token, user_id, store, now):
    if not isinstance(submitted_token, str):
        return False
    token = submitted_token.strip()
    if not token:
        return False
    entry = store.get(token)
    if not isinstance(entry, dict):
        return False
    if entry.get("user_id") != user_id:
        return False
    exp = entry.get("exp")
    if isinstance(exp, bool) or not isinstance(exp, (int, float)) or not isfinite(exp):
        return False
    if isinstance(now, bool) or not isinstance(now, (int, float)) or not isfinite(now):
        return False
    if now >= exp:
        return False
    return True
